// === Tab: mySketch.js ===
canvasSize = 500;
particles = [];
redP = [];
yellowP = [];
greenP = [];

// SETUP
function setup() {
	createCanvas(canvasSize, canvasSize);
	background(100);
	redP = group(200, color(255,0,0), 5);
	yellowP = group(200, color(255,255,0), 5);
	greenP = group(200,color(0,255,0), 5);
}

// ALGORITHM
class Particle {
	constructor(loc, color, diameter = 20) {
		this.loc = loc;
		this.diameter = diameter;
		this.vel = createVector(1,1);
		this.color = color;
	}
	show() {
		noStroke();
		fill(this.color);
		const {x, y} = this.loc;
		circle(x, y, this.diameter);
	}
	radius() {
		return this.diameter / 2;
	}
	edge(coordinate) {
		return this.radius() + this.loc[coordinate];
	}
}

function group(number, color, radius) {
	const g = [];
	for(let i = 0; i < number; i++) {
		const loc = createVector(random(canvasSize), random(canvasSize));
		g.push(new Particle(loc, color, radius));
		particles.push(g[i]);

	}
	return g;
}

function single(p1, g) {
	let fx = 0;
	let fy = 0;
	let dx = p1.edge("x") - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
	let dy = p1.edge("y") - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
	let d = Math.sqrt(dx*dx + dy*dy);
	if(d > 0 && d < 80) {
		let F = g * (1/d);
		fx += (F * dx);
		fy += (F * dy);
	}
	p1.vel.x = (p1.vel.x + fx) * 0.5;
	p1.vel.y = (p1.vel.y + fy) * 0.5;
	p1.loc.x += p1.vel.x;
	p1.loc.y += p1.vel.y;
}

function rule(p1, p2, g) {
	for(let i = 0; i < p1.length; i++) {
		var fx = 0;
		var fy = 0;
		let a = p1[i];
		for(let j = 0; j < p2.length; j++) {
			let b = p2[j];
			var dx = a.edge("x") - b.edge("x");
			var dy = a.edge("y") - b.edge("y");
			var d = Math.sqrt(dx*dx + dy*dy);
			if(d > 0 && d < 80) {
				var F = g * (1/d);
				fx += (F * dx);
				fy += (F * dy);
			}
		}
		a.vel.x = (a.vel.x + fx) * 0.5;
		a.vel.y = (a.vel.y + fy) * 0.5;
		a.loc.x += a.vel.x;
		a.loc.y += a.vel.y;
		if(a.edge("x") <= 0 || a.edge("x") >= canvasSize) a.vel.x*=-1;
		if(a.edge("y") <= 0 || a.edge("y") >= canvasSize) a.vel.y*=-1;

	}
}

// ANIMATE
function draw() {
	rule(redP, redP, 0.1);
	rule(yellowP, redP, 0.15);
	rule(greenP, greenP, -0.7);
	rule(greenP, redP, -0.2);
	rule(redP, greenP, -0.1);
	background(0);
	for(let i = 0; i < particles.length; i++) {
		single(particles[i], 1);
		particles[i].show();
	}
}

